class Solution {
    public int maxWidthOfVerticalArea(int[][] points){
        Arrays.sort(points,Comparator.comparingInt(point->point[0]));
        int answer=0;
        for(int i=1;i<points.length;i++)answer=Math.max(answer,points[i][0]-points[i-1][0]);
        return answer;
    }
}

code.kotlin:
class Solution {
    fun maxWidthOfVerticalArea(points:Array<IntArray>):Int{
        val x=points.map{
            it[0]
        }.sorted();
        var answer=0;
        for(i in 1 until x.size)answer=maxOf(answer,x[i]-x[i-1]);
        return answer
    }
}

