class Solution {
    public: int maxWidthOfVerticalArea(vector<vector<int>>& points){
        sort(points.begin(),points.end());
        int answer=0;
        for(int i=1;i<(int)points.size();++i)answer=max(answer,points[i][0]-points[i-1][0]);
        return answer;
    }
};
